const item = $input.item.json;
const output = item.output || '';

// Récupérer le chatId depuis les noeuds précédents
let chatId = '';
try { chatId = $('Données Vocale').item.json.chatId; } catch(e) {}
if (!chatId) {
  try { chatId = $('Router Message').item.json.chatId; } catch(e) {}
}

// Détecter les URLs d'images DALL-E (OpenAI)
const dalleRegex = /https?:\/\/oaidalleapiprodscus\.blob\.core\.windows\.net\/[^\s<>"]+/gi;
// Détecter toute URL d'image générique
const imgRegex = /https?:\/\/[^\s<>"]+\.(?:png|jpg|jpeg|gif|webp)(\?[^\s<>"]*)?/gi;

const dalleMatches = output.match(dalleRegex);
const imgMatches = output.match(imgRegex);

let imageUrl = null;
if (dalleMatches && dalleMatches.length > 0) {
  imageUrl = dalleMatches[0];
} else if (imgMatches && imgMatches.length > 0) {
  imageUrl = imgMatches[0];
}

// Préparer la légende: texte sans l'URL
let caption = output
  .replace(dalleRegex, '')
  .replace(imgRegex, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

if (!caption) {
  caption = '🎨 Image générée par DALL-E 3';
}

// Limiter la légende à 1024 caractères (limite Telegram)
if (caption.length > 1024) {
  caption = caption.substring(0, 1021) + '...';
}

return [{
  json: {
    output: output,
    imageUrl: imageUrl,
    hasImage: imageUrl !== null,
    caption: caption,
    chatId: chatId
  }
}];
